#include <cuda_runtime.h>
#include <cstdio>
#include <cstring>
#include <vector>
#include <algorithm>
#include "../mandelbrot-cuda/common.hpp"
#include "../mandelbrot-cuda/mandel.hpp"
struct Case{int rows,cols,cap;};
int main(){const int G=16,guard=-1234567;std::vector<Case>cases={{32,48,0},{32,48,1},{32,48,2},{65,97,100},{1080,1920,100}};size_t total=0;for(auto c:cases)total+=c.rows*c.cols;std::vector<int>oracle(total);FILE*f=fopen("oracle_i32.bin","rb");if(!f||fread(oracle.data(),4,total,f)!=total)return 2;fclose(f);bool all=true;static_assert(sizeof(MandelParameters)==12);
 for(int trial=0;trial<=5;trial++){bool ok=true;int bad=0;size_t offset=0;std::vector<int>prefix,outputs;std::vector<double>times;
 for(auto c:cases){int n=c.rows*c.cols;std::vector<int>initial(n+2*G,guard),params(2*G+3,guard),before(initial.size()),out(initial.size()),pback(params.size()),after(params.size());params[G]=c.rows;params[G+1]=c.cols;params[G+2]=c.cap;int*d,*dp;cudaMalloc(&d,initial.size()*4);cudaMalloc(&dp,params.size()*4);cudaMemcpy(d,initial.data(),initial.size()*4,cudaMemcpyHostToDevice);cudaMemcpy(dp,params.data(),params.size()*4,cudaMemcpyHostToDevice);auto launch=[&](){mandel<<<dim3((c.rows+15)/16,(c.cols+15)/16),dim3(16,16)>>>(d+G,(const MandelParameters*)(dp+G),c.rows,c.cols);};if(trial==0){launch();ok &=cudaGetLastError()==cudaSuccess&&cudaDeviceSynchronize()==cudaSuccess;cudaFree(d);cudaFree(dp);offset+=n;continue;}cudaMemcpy(before.data(),d,before.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(pback.data(),dp,pback.size()*4,cudaMemcpyDeviceToHost);ok &=before==initial&&pback==params;cudaDeviceSynchronize();common::MyTimer timer;launch();ok &=cudaGetLastError()==cudaSuccess&&cudaDeviceSynchronize()==cudaSuccess;times.push_back(timer.elapsed().count());cudaMemcpy(out.data(),d,out.size()*4,cudaMemcpyDeviceToHost);cudaMemcpy(after.data(),dp,after.size()*4,cudaMemcpyDeviceToHost);ok &=after==params;for(int j=0;j<G;j++)bad+=out[j]!=guard||out[out.size()-G+j]!=guard;for(int j=0;j<n;j++){bad+=out[G+j]!=oracle[offset+j];ok &=out[G+j]>=0&&out[G+j]<=c.cap;}prefix.insert(prefix.end(),before.begin(),before.end());prefix.insert(prefix.end(),pback.begin(),pback.end());outputs.insert(outputs.end(),out.begin(),out.end());cudaFree(d);cudaFree(dp);offset+=n;
 }if(!trial){if(!ok)return 3;continue;}ok &=bad==0;all &=ok;std::vector<int>artifact=prefix;artifact.insert(artifact.end(),outputs.begin(),outputs.end());char path[80];snprintf(path,80,"output_trial%d.bin",trial);f=fopen(path,"wb");if(!f)return 4;fwrite(artifact.data(),4,artifact.size(),f);fclose(f);double sum=0;for(double t:times)sum+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%d,\"max_rel_error\":0,\"timing_region\":\"sum5_source_mandel_kernel_hostwindows\",\"jit_excluded\":true,\"path_times_seconds\":[",trial,sum,ok?"true":"false",artifact.size(),bad?1:0);for(size_t j=0;j<times.size();j++)printf("%s%.12g",j?",":"",times[j]);printf("],\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",path,artifact.size());
 }puts(all?"PASS":"FAIL");return all?0:1;}
